        if (km < 0) {
            System.out.println("Distance invalide");
        } else if (km <= 3) {
            System.out.println("Tarif : 200 FCFA");
        } else if (km <= 8) {
            System.out.println("Tarif : 400 FCFA");
        } else {
            System.out.println("Tarif : 700 FCFA");
        }
    }
}

